// This file is generated by AI.

// 路径工具与项目文件夹名清理的断言。

import { describe, expect, it } from 'vitest';

import { baseName, joinPath, samePath, sanitizeFolderName, stripTrailingSeparator, toPosix } from '../src/lib/paths';

describe('路径工具', () => {
  it('取最后一段并忽略结尾分隔符', () => {
    expect(baseName('C:\\proj\\game\\scene\\start.txt')).toBe('start.txt');
    expect(baseName('C:\\proj\\我的游戏\\')).toBe('我的游戏');
    expect(baseName('/home/u/proj')).toBe('proj');
  });

  it('去掉结尾分隔符', () => {
    expect(stripTrailingSeparator('C:\\a\\b\\')).toBe('C:\\a\\b');
    expect(stripTrailingSeparator('C:\\a\\b')).toBe('C:\\a\\b');
  });

  it('比较路径时统一分隔符与大小写', () => {
    expect(samePath('C:\\A\\b.txt', 'c:/a/B.TXT')).toBe(true);
    expect(samePath('C:\\a\\b', 'C:\\a\\c')).toBe(false);
  });

  it('拼路径时不会出现双分隔符', () => {
    expect(joinPath('C:\\proj\\', 'game', 'config.txt')).toBe('C:\\proj\\game\\config.txt');
    expect(joinPath('', 'game')).toBe('game');
  });

  it('转换成正斜杠', () => {
    expect(toPosix('C:\\a\\b')).toBe('C:/a/b');
  });
});

describe('sanitizeFolderName', () => {
  it('把非法字符换成下划线', () => {
    expect(sanitizeFolderName('我的:游戏?')).toBe('我的_游戏_');
  });

  it('去掉首尾的点与空白 (Windows 会把它们吃掉)', () => {
    expect(sanitizeFolderName('  .星海.  ')).toBe('星海');
  });

  it('合并连续空白', () => {
    expect(sanitizeFolderName('星  海   叙事')).toBe('星 海 叙事');
  });

  it('全是非法字符时给出空串, 由调用方报错', () => {
    expect(sanitizeFolderName('...')).toBe('');
  });
});
